const Component = () => {
  const [endX, setEndX] = useState(70);
  const ref = useCanvas((ctx, { width, color }) => {
    const start = { x: 32, y: 32 };
    const end = { x: (width * endX) / 100, y: 128 };
    const gradient = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
    gradient.addColorStop(0, color("tag-2"));
    gradient.addColorStop(0.5, color("tag-3"));
    gradient.addColorStop(1, color("tag-5"));
    ctx.beginPath();
    ctx.strokeStyle = gradient;
    ctx.lineWidth = 12;
    ctx.lineCap = "round";
    ctx.moveTo(start.x, start.y);
    ctx.lineTo(end.x, end.y);
    ctx.stroke();
    note(ctx, color, "(x1, y1)", start.x + 14, start.y - 14);
    note(ctx, color, "(x2, y2)", end.x + 14, end.y + 14);
  }, [endX]);

  return (
    <Demo>
      <Stage canvasRef={ref} height={160} />
      <Row>
        <Slider label="x2" value={endX} min={20} max={90} onChange={setEndX} format={value => `${value}%`} />
        <Chip>createLinearGradient(x1, y1, x2, y2)</Chip>
      </Row>
    </Demo>
  );
};

