const Component = () => {
  const [innerRadius, setInnerRadius] = useState(0);
  const [offset, setOffset] = useState(0);
  const ref = useCanvas((ctx, { width, color }) => {
    const cx = width / 2;
    const cy = 130;
    const radius = 110;
    // 内圆圆心可偏移，两个圆之间的区域是渐变带
    const gradient = ctx.createRadialGradient(cx + offset, cy, innerRadius, cx, cy, radius);
    gradient.addColorStop(0, color("tag-2"));
    gradient.addColorStop(0.5, color("tag-3"));
    gradient.addColorStop(1, color("tag-5"));
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.save();
    ctx.setLineDash([4, 4]);
    ctx.strokeStyle = color("ink-inverse");
    ctx.lineWidth = 1.5;
    if (innerRadius > 0) {
      ctx.beginPath();
      ctx.arc(cx + offset, cy, innerRadius, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();
  }, [innerRadius, offset]);

  return (
    <Demo>
      <Stage canvasRef={ref} height={260} />
      <Row>
        <Slider label="r1" value={innerRadius} min={0} max={80} onChange={setInnerRadius} format={value => `${value}px`} />
        <Slider label="x1 偏移" value={offset} min={-60} max={60} onChange={setOffset} format={value => `${value}px`} />
      </Row>
      <Chip>createRadialGradient(x1, y1, r1, x2, y2, r2)</Chip>
    </Demo>
  );
};

