const REPETITIONS = ["repeat", "repeat-x", "repeat-y", "no-repeat"];

const Component = () => {
  const [repetition, setRepetition] = useState("repeat");
  const [tile, setTile] = useState(40);
  const ref = useCanvas((ctx, { width, height, color }) => {
    // 用一张离屏 canvas 画棋盘格作为纹理
    const patternCanvas = document.createElement("canvas");
    patternCanvas.width = tile;
    patternCanvas.height = tile;
    const patternCtx = patternCanvas.getContext("2d");
    if (!patternCtx) return;
    patternCtx.fillStyle = color("accent");
    patternCtx.fillRect(0, 0, tile / 2, tile / 2);
    patternCtx.fillRect(tile / 2, tile / 2, tile / 2, tile / 2);
    patternCtx.fillStyle = color("accent-soft");
    patternCtx.fillRect(tile / 2, 0, tile / 2, tile / 2);
    patternCtx.fillRect(0, tile / 2, tile / 2, tile / 2);
    const pattern = ctx.createPattern(patternCanvas, repetition);
    if (!pattern) return;
    ctx.fillStyle = pattern;
    ctx.fillRect(0, 0, width, height);
  }, [repetition, tile]);

  return (
    <Demo>
      <Stage canvasRef={ref} height={220} />
      <Row>
        <ui.RadioGroup label="repetition" value={repetition} onValueChange={setRepetition} orientation="horizontal">
          {REPETITIONS.map(value => (
            <ui.Radio key={value} value={value} label={value} />
          ))}
        </ui.RadioGroup>
        <Slider label="纹理尺寸" value={tile} min={16} max={80} step={4} onChange={setTile} format={value => `${value}px`} />
      </Row>
    </Demo>
  );
};
